/**
 * The account's last plan, kept on this device for one job: Today draws the
 * trial's chip and its moments on a cold start (a reload, an app launch)
 * with the rest of the page, offline-first, instead of only after the
 * learner leaves Today and comes back (owner's report, 2026-10-13).
 *
 * It is the server's last answer, by account, written only when it changed
 * and cleared with the rest of the local data on sign-out. It never sells,
 * locks or unlocks anything: the paywall, the Plan page and every Pro check
 * still read `useBilling`, which only the network fills. Everything drawn
 * from it is checked against the clock: a trial past its `endsAt` is not
 * running, an offer past its `closesAt` is not open.
 */
import type { ApiBillingState } from '@/api/types.js';
import { getMeta, setMeta, type StoredPlanSnapshot } from '@/db/schema.js';

/** The plan as worth keeping: without the server's clock reading, which changes on every answer. */
function keepable(state: ApiBillingState): ApiBillingState {
  const { serverNow: _now, ...rest } = state;
  return rest;
}

/** Notes the server's answer for this account, when it differs from what is kept. */
export async function notePlanSnapshot(account: string | undefined, state: ApiBillingState): Promise<void> {
  if (account === undefined || account === '') return;
  const next = keepable(state);
  const kept = await getMeta('planSnapshot');
  if (kept?.account === account && JSON.stringify(kept.state) === JSON.stringify(next)) return;
  await setMeta('planSnapshot', { account, at: new Date().toISOString(), state: next });
}

/** The kept plan, only when it is this account's. */
export function snapshotFor(
  snapshot: StoredPlanSnapshot | null | undefined,
  account: string | undefined,
): ApiBillingState | undefined {
  if (snapshot === null || snapshot === undefined || account === undefined) return undefined;
  return snapshot.account === account ? snapshot.state : undefined;
}
